mapper.update:
update tb_refund_info
refund_id = #{refundId}, total_fee = #{totalFee}, refund = #{refund}, reason = #{reason}, refund_status = #{refundStatus}, content_return = #{contentReturn}, content_notify = #{contentNotify}, create_time = #{createTime}, update_time = #{updateTime},
where refund_number = #{refundNumber}

mapper.select:
select * from tb_refund_info
where refund_status = #{refundStatus} AND
      create_time < #{time}
